using System;using System.Collections.Generic;using System.Data;using System.Drawing;using System.Globalization;using System.Linq;using System.Windows.Forms;
namespace XzyBattleStats {
sealed class OpponentRole {public Role Role;public int Games,Wins;}
sealed class Opponent {public string Identity,Uid,Name,Basis,Roles;public int Games,Wins;public List<Role> Characters;public List<OpponentRole> RoleRows=new List<OpponentRole>();}
static class OpponentStats {
 public static string Key(Battle b,Player p,string region){return J.Json.Serialize(new[]{string.IsNullOrEmpty(b.ViewGameCode)?region:b.ViewGameCode,string.IsNullOrWhiteSpace(p.Uid)?"name":"uid",string.IsNullOrWhiteSpace(p.Uid)?p.Name:p.Uid});}
 public static List<Opponent> Rows(Snapshot s,int mode,string filter=""){
  var encounters=s.Battles.Where(b=>mode==0||b.Mode==mode).SelectMany(b=>b.EnemyTeamPlayers.Where(p=>!string.IsNullOrWhiteSpace(p.Uid)||!string.IsNullOrWhiteSpace(p.Name)).GroupBy(p=>Key(b,p,s.GameCode)).Select(g=>new{Battle=b,Player=g.First(),Identity=g.Key})).ToList();
  return encounters.GroupBy(x=>x.Identity).Select(g=>{var latest=g.OrderByDescending(x=>x.Battle.Start).ThenBy(x=>x.Battle.Id,StringComparer.Ordinal).ToList();var roles=g.SelectMany(x=>x.Player.Roles.GroupBy(r=>r.Id).Select(z=>new{Role=z.First(),Win=x.Battle.Result=="win"})).GroupBy(x=>x.Role.Id).OrderByDescending(x=>x.Count()).ToList();return new Opponent{Identity=g.Key,Uid=latest[0].Player.Uid,Name=latest.Select(x=>x.Player.Name).FirstOrDefault(n=>!string.IsNullOrWhiteSpace(n))??"未知昵称",Basis=string.IsNullOrWhiteSpace(latest[0].Player.Uid)?"昵称识别":"账号识别",Games=g.Count(),Wins=g.Count(x=>x.Battle.Result=="win"),Characters=roles.Select(x=>x.First().Role).ToList(),RoleRows=roles.Select(x=>new OpponentRole{Role=x.First().Role,Games=x.Count(),Wins=x.Count(y=>y.Win)}).ToList(),Roles=string.Join("；",roles.Select(x=>x.First().Role.Name+" "+x.Count()+" 场 / 你的胜率 "+(100.0*x.Count(y=>y.Win)/x.Count()).ToString("0.0")+"%"))};}).Where(p=>string.IsNullOrEmpty(filter)||(filter.StartsWith("@opponent:")?p.Identity==filter.Substring(10):p.Name.IndexOf(filter,StringComparison.CurrentCultureIgnoreCase)>=0)).OrderByDescending(p=>p.Games).ThenBy(p=>p.Name).ThenBy(p=>p.Identity,StringComparer.Ordinal).ToList();
 }
 static string Quote(string value){value=value??"";if(value.Length>0&&"=+-@\t\r".Contains(value[0]))value="'"+value;return "\""+value.Replace("\"","\"\"")+"\"";}
 public static string Csv(Snapshot s,bool all){var lines=new List<string>{"模式,对手昵称,交手场数,你的胜场,你的负场,你的胜率,对手角色场数与你的胜率"};foreach(int mode in all?new[]{0}:Stats.Modes)foreach(var p in Rows(s,mode))lines.Add(string.Join(",",new[]{Quote(Stats.Label(mode)),Quote(p.Name),p.Games.ToString(),p.Wins.ToString(),(p.Games-p.Wins).ToString(),(100.0*p.Wins/p.Games).ToString("0.00",CultureInfo.InvariantCulture)+"%",Quote(p.Roles)}));return string.Join("\r\n",lines);}
}
sealed partial class NativeForm {
 readonly DataGridView opponents=Grid(),opponentRoles=Grid();readonly ComboBox opponentChoice=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=260};readonly TextBox opponentSearch=new TextBox{Width=200};readonly Label opponentScope=new Label(),opponentRoleName=new Label{Dock=DockStyle.Top,Height=34,Padding=new Padding(6),AutoEllipsis=true,UseMnemonic=false};bool updatingOpponents,bindingOpponentRows;FoldPanel opponentRoleFold;DataTable opponentSourceTable;List<Opponent> opponentDisplayRows=new List<Opponent>();
 TabPage OpponentPage(){var page=new TabPage("对手战绩");page.Controls.Add(opponents);var roleContent=new Panel();roleContent.Controls.Add(opponentRoles);roleContent.Controls.Add(opponentRoleName);opponentRoleFold=(FoldPanel)Fold("对手角色与胜率（选中对手后展开）",roleContent,250,DockStyle.Bottom);page.Controls.Add(opponentRoleFold);page.Layout+=delegate{if(opponentRoleFold.Open){int available=page.ClientSize.Height-page.Controls.Cast<Control>().Where(c=>c!=opponentRoleFold&&(c.Dock==DockStyle.Top||c.Dock==DockStyle.Bottom)).Sum(c=>c.Height);int height=Math.Min(Math.Max(30,available-60),30+Math.Max(70,Math.Min(250,(available-30)/2)));if(opponentRoleFold.Height!=height)opponentRoleFold.Height=height;}};var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,Padding=new Padding(6)};bar.Controls.Add(FilterLabel("对手昵称"));bar.Controls.Add(opponentChoice);bar.Controls.Add(FilterLabel("搜索昵称"));bar.Controls.Add(opponentSearch);bar.Controls.Add(Action("清除筛选",()=>{opponentSearch.Clear();opponentChoice.SelectedIndex=0;}));page.Controls.Add(bar);opponentScope.Dock=DockStyle.Bottom;opponentScope.Height=50;opponentScope.Padding=new Padding(6);page.Controls.Add(opponentScope);opponentChoice.SelectedIndexChanged+=delegate{if(!updatingOpponents)RenderOpponents(false);};opponentSearch.TextChanged+=delegate{RenderOpponents(false);};opponents.CurrentCellChanged+=delegate{if(!bindingOpponentRows)RenderOpponentRoles();};opponents.Sorted+=delegate{if(!bindingOpponentRows)RenderOpponentRoles();};return page;}
 Opponent SelectedOpponent(){var row=opponents.CurrentRow;if(row==null||opponentSourceTable==null)return null;var view=row.DataBoundItem as DataRowView;if(view==null||view.Row.Table!=opponentSourceTable)return null;int index=opponentSourceTable.Rows.IndexOf(view.Row);return index>=0&&index<opponentDisplayRows.Count?opponentDisplayRows[index]:null;}
 void RenderOpponentRoles(){var selected=SelectedOpponent();var table=new DataTable();table.Columns.Add("头像",typeof(Image));table.Columns.Add("对手角色");foreach(string column in new[]{"交手场数","你的胜场","你的负场"})table.Columns.Add(column,typeof(int));table.Columns.Add("胜率",typeof(double));if(selected!=null)foreach(var row in selected.RoleRows)table.Rows.Add(AvatarImages.Get(row.Role),row.Role.Name,row.Games,row.Wins,row.Games-row.Wins,100.0*row.Wins/row.Games);opponentRoleName.Text=selected==null?"请先在上方选择一个对手。":selected.Name+" · "+selected.RoleRows.Count+" 个角色";opponentRoleName.Height=Math.Max(34,opponentRoleName.Font.Height+opponentRoleName.Padding.Vertical+4);BindSorted(opponentRoles,table,"交手场数");opponentRoles.Columns["头像"].AutoSizeMode=DataGridViewAutoSizeColumnMode.None;opponentRoles.Columns["头像"].Width=AvatarRowHeight()+8;}
 void RenderOpponents(bool fill=true){var previous=SelectedOpponent();string previousIdentity=previous==null?"":previous.Identity;var table=new DataTable();table.Columns.Add("头像",typeof(Image));table.Columns.Add("对手昵称");foreach(string column in new[]{"交手场数","你的胜场","你的负场"})table.Columns.Add(column,typeof(int));table.Columns.Add("胜率",typeof(double));var displayed=new List<Opponent>();if(data!=null){var all=OpponentStats.Rows(data,mode);if(fill){updatingOpponents=true;string selected=Chosen(opponentChoice);opponentChoice.Items.Clear();opponentChoice.Items.Add(new Choice{Id="",Name="全部对手"});var numbers=new Dictionary<string,int>();foreach(var p in all){int n;numbers.TryGetValue(p.Name,out n);numbers[p.Name]=n+1;opponentChoice.Items.Add(new Choice{Id="@opponent:"+p.Identity,Name=p.Name+(all.Count(x=>x.Name==p.Name)>1?"（同名 "+(n+1)+"）":"")+" · "+p.Games+" 场"});}opponentChoice.SelectedIndex=0;for(int i=0;i<opponentChoice.Items.Count;i++)if(((Choice)opponentChoice.Items[i]).Id==selected)opponentChoice.SelectedIndex=i;updatingOpponents=false;}displayed=OpponentStats.Rows(data,mode,Chosen(opponentChoice)).Where(p=>p.Name.IndexOf(opponentSearch.Text.Trim(),StringComparison.CurrentCultureIgnoreCase)>=0).ToList();foreach(var p in displayed)table.Rows.Add(p.Characters.Count>0?AvatarImages.Get(p.Characters[0]):null,p.Name,p.Games,p.Wins,p.Games-p.Wins,100.0*p.Wins/p.Games);opponentScope.Text="胜率为你对该玩家的胜率；同局同一对手计一次。跨账号汇总按账号视角计数。";}else opponentScope.Text="请先导入带有敌方玩家信息的战绩。旧缓存可重新导入原始官网 JSON 或增量补查。";bindingOpponentRows=true;try{opponentSourceTable=table;opponentDisplayRows=displayed;BindSorted(opponents,table,"交手场数");foreach(DataGridViewRow row in opponents.Rows){var view=row.DataBoundItem as DataRowView;if(view!=null&&displayed[table.Rows.IndexOf(view.Row)].Identity==previousIdentity){opponents.CurrentCell=row.Cells["对手昵称"];break;}}}finally{bindingOpponentRows=false;}RenderOpponentRoles();}
}
}
